/* @lc app=leetcode id=1948 lang=kotlin */ class Solution { class N(val ch: java.util.TreeMap<String, N> = java.util.TreeMap(), var s: String = "") fun ser(n: N, cnt: HashMap<String, Int>): String = n.ch.entries.joinToString("") { (k, c) -> "(" + k + ser(c, cnt) + ")" }.also { n.s = it }.also { if (it.isNotEmpty()) cnt.merge(it, 1) { a, b -> a + b } } fun col(n: N, path: List<String>, cnt: Map<String, Int>): List<List<String>> = n.ch.flatMap { (k, c) -> if (c.s.isNotEmpty() && cnt[c.s]!! > 1) emptyList() else (path + k).let { p -> listOf(p) + col(c, p, cnt) } } fun deleteDuplicateFolder(paths: List<List<String>>): List<List<String>> = N().let { root -> paths.forEach { p -> p.fold(root) { n, nm -> n.ch.getOrPut(nm) { N() } } }.let { HashMap<String, Int>().let { cnt -> ser(root, cnt).let { col(root, listOf(), cnt) } } } } }